class ChatRoom {
  private participants: { [name: string]: Participant } = {};
  register(p: Participant) { this.participants[p.name] = p; p.room = this; }
  send(sender: string, message: string) {
    Object.values(this.participants).forEach(p => { if (p.name !== sender) p.receive(message); });
  }
}

class Participant {
  constructor(public name: string, public room?: ChatRoom) {}
  send(message: string) { this.room?.send(this.name, message); }
  receive(message: string) { console.log(this.name, message); }
}

class Hub {
  private clients: Record<string, Function[]> = {};
  register(type: string, handler: Function) { this.clients[type] = this.clients[type] || []; this.clients[type].push(handler); }
  send(msg: { type: string; payload: any }) {
    if (msg.type === 'A') this.clients['A']?.forEach(h => h(msg.payload));
    else if (msg.type === 'B') this.clients['B']?.forEach(h => h(msg.payload));
    else if (msg.type === 'C') this.clients['C']?.forEach(h => h(msg.payload));
    else this.clients['default']?.forEach(h => h(msg.payload));
  }
}

